const feeds = [
  { source: 'TechCrunch AI',        url: 'https://techcrunch.com/category/artificial-intelligence/feed/' },
  { source: 'The Verge AI',         url: 'https://www.theverge.com/ai-artificial-intelligence/rss/index.xml' },
  { source: 'Hacker News',          url: 'https://news.ycombinator.com/rss' },
  { source: 'MIT Technology Review AI', url: 'https://www.technologyreview.com/topic/artificial-intelligence/feed/' },
  { source: 'LangChain Blog',       url: 'https://blog.langchain.com/rss.xml' },
  { source: 'OpenAI News',          url: 'https://openai.com/news/rss.xml' },
  { source: 'Anthropic News',       url: 'https://www.anthropic.com/news/rss.xml' },
  { source: 'TechCrunch Startups (funding / hiring signals)', url: 'https://techcrunch.com/category/startups/feed/' }
];
// No Internshala anywhere in this workflow.
return feeds.map(f => ({ json: f }));

// Normalise RSS items. Keep AI / AI-agent / hiring-signal items only, newest first,
// at most 6 per source so one noisy feed cannot dominate the brief.
const FIT = /ai|agent|llm|gpt|language model|machine learning|startup|funding|hiring|job|intern/i;
const seen = {};
const out = [];
for (const item of $input.all()) {
  const src = item.json.source || 'unknown';
  const feed = item.json.feed || {};
  const entries = Array.isArray(feed) ? feed : (feed.items || feed.entries || [feed]);
  for (const e of entries) {
    const title = e.title || e.name || '';
    const link = e.link || e.url || e.guid || '';
    if (!title || !link) continue;
    if (!FIT.test(title + ' ' + (e.description || e.summary || e.contentSnippet || ''))) continue;
    if ((seen[src] || 0) >= 6) continue;
    seen[src] = (seen[src] || 0) + 1;
    out.push({ json: {
      source: src,
      title: String(title).trim(),
      url: String(link).trim(),
      summary: String(e.description || e.summary || e.contentSnippet || '').replace(/<[^>]+>/g, '').trim().slice(0, 400),
      published: e.pubDate || e.isoDate || e.published || ''
    } });
  }
}
return out;

// Drop any item whose URL is already in the Briefed Log sheet.
// Reads the parsed items from the earlier node, not from this node's input.
const parsed = $('Parse & Filter Items').all().map(i => i.json);
const briefed = new Set($input.all().map(i => String(i.json.URL || i.json.url || '').trim().toLowerCase()));
const fresh = parsed.filter(r => !briefed.has(String(r.url || '').trim().toLowerCase()));
return fresh.map(r => ({ json: r }));

// Bundle the fresh items into one research pack for the Writer agent.
// Cap at 15 items so the prompt stays focused. Every item keeps its source URL.
const items = $input.all().map(i => i.json).slice(0, 15);
const lines = items.map((it, idx) =>
  (idx + 1) + '. [' + it.source + '] ' + it.title + ' — ' + it.url +
  (it.summary ? ' | ' + it.summary : '')
).join('\n');
return [{ json: {
  briefDate: new Date().toLocaleDateString('en-IN', { timeZone: 'Asia/Kolkata', year: 'numeric', month: 'long', day: 'numeric' }),
  itemCount: items.length,
  items,
  researchText: lines
} }];

parameters.text:
Write Siva's morning brief from this research pack:

{{ $json.researchText }}

Reply with ONLY this JSON, no other text:
{"topStories": [{"title": "...", "whyItMatters": "one line", "url": "..."}], "jobLeads": [{"title": "...", "company": "...", "why": "one line", "url": "..."}], "learnToday": {"topic": "...", "why": "one line", "url": "..."}}

Rules: exactly 5 top stories (fewer only if fewer than 5 items were supplied); 2-3 job leads, ONLY from items that are real hiring/funding signals in the pack — if the pack has no real job lead, use an empty array, never invent one; one 'learn today' topic from the pack. Every URL must be copied exactly from the research pack.

