// Extract the Writer agent's JSON draft. If it is not valid JSON, keep the
// research pack attached and mark the draft empty so the Reviewer rejects it.
const raw = $input.first().json.output || $input.first().json.text || '';
let draft = {};
try { draft = JSON.parse(raw); } catch (e) {
  const m = String(raw).match(/\{[\s\S]*\}/);
  try { draft = m ? JSON.parse(m[0]) : {}; } catch (e2) { draft = {}; }
}
const pack = $('Aggregate Research').first().json;
return [{ json: { ...pack, draft, revisionCount: 0 } }];

parameters.text:
Review this draft brief against the research pack.

RESEARCH PACK (the only trusted sources):
{{ $json.researchText }}

DRAFT:
{{ JSON.stringify($json.draft) }}

Reply with ONLY this JSON, no other text:
{"approved": true/false, "needsRevision": true/false, "issues": ["..."], "cleanedDraft": {same shape as the draft, with unverified or invented items REMOVED, URLs corrected to the research pack, and nothing added}}

Rules: drop any story, job lead or learn-topic whose URL is not in the research pack or whose claim is not supported by it. Set needsRevision=true (and approved=false) only if removing bad items leaves fewer than 3 top stories or an empty job-leads section that should have had one — otherwise approve the cleaned draft. Never add new items.

