// Extract the Reviewer agent's JSON. Default to NOT approved if unparsable —
// an unreviewed draft must never be sent.
const raw = $input.first().json.output || $input.first().json.text || '';
let review = {};
try { review = JSON.parse(raw); } catch (e) {
  const m = String(raw).match(/\{[\s\S]*\}/);
  try { review = m ? JSON.parse(m[0]) : {}; } catch (e2) { review = {}; }
}
const prev = $('Parse Writer Draft').first().json;
return [{ json: {
  ...prev,
  approved: review.approved === true,
  needsRevision: review.needsRevision === true,
  issues: review.issues || [],
  cleanedDraft: review.cleanedDraft || prev.draft
} }];

parameters.text:
Revise this draft brief using the Reviewer's issues. Do not add new stories or job leads.

RESEARCH PACK (the only trusted sources):
{{ $json.researchText }}

DRAFT:
{{ JSON.stringify($json.cleanedDraft) }}

REVIEWER ISSUES:
{{ $json.issues.join('\n') }}

Reply with ONLY the corrected brief JSON in the same shape as the draft ({topStories, jobLeads, learnToday}), every URL copied exactly from the research pack.

