// Extract the revision's JSON. Mark revisionCount=1 so the loop cannot run again.
const raw = $input.first().json.output || $input.first().json.text || '';
let draft = {};
try { draft = JSON.parse(raw); } catch (e) {
  const m = String(raw).match(/\{[\s\S]*\}/);
  try { draft = m ? JSON.parse(m[0]) : {}; } catch (e2) { draft = {}; }
}
const prev = $('Parse Review').first().json;
return [{ json: { ...prev, draft, cleanedDraft: draft, revisionCount: 1, approved: true } }];

// Mechanical check, no AI: every brief item's URL must appear in the fetched
// research items. Drop anything that does not. The brief that goes out is the
// reviewer-approved version (or the once-revised version) minus unverifiable items.
const prev = $input.first().json;
const srcUrls = new Set((prev.items || []).map(i => String(i.url || '').trim().toLowerCase()));
const draft = prev.cleanedDraft || prev.draft || {};
const keep = (arr) => (arr || []).filter(it => it && it.url && srcUrls.has(String(it.url).trim().toLowerCase()));
const brief = {
  topStories: keep(draft.topStories),
  jobLeads: keep(draft.jobLeads),
  learnToday: (draft.learnToday && draft.learnToday.url && srcUrls.has(String(draft.learnToday.url).trim().toLowerCase())) ? draft.learnToday : null
};
return [{ json: { ...prev, brief, verifiedCount: brief.topStories.length } }];

